mapper.update:
update defense_topics
set topic_name = #{topicName}, topic_description = #{topicDescription},
defense_time = #{defenseTime}, updated_at = #{updatedAt}
where topic_id = #{topicId}

mapper.select:
SELECT * FROM defense_topics
ORDER BY created_at DESC
    LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM defense_answers da
JOIN defense_questions dq ON da.question_id = dq.question_id
WHERE dq.topic_id = #{topicId}

mapper.update:
UPDATE defense_questions
SET question = #{question},
    standard_answer = #{standardAnswer},
    updated_at = #{updatedAt}
WHERE question_id = #{questionId}
